pub struct Session<'a, E: Engine<'a>> {
    /// The SQL engine.
    engine: &'a E,
    /// The current transaction, if any.
    txn: Option<E::Transaction>,
}

impl<'a, E: Engine<'a>> Session<'a, E> {
    /// Creates a new session using the given SQL engine.
    pub fn new(engine: &'a E) -> Self {
        Self {
            engine,
            txn: None,
        }
    }

    /// Executes a client statement.
    pub fn execute(&mut self, statement: &str) -> Result<StatementResult> {
        let stmt = Parser::parse(statement)?;
        let result = self.with_txn(false, |txn| {
            let plan = Plan::build(stmt.clone(), txn)?;
            let plan = plan.optimize()?;
            plan.execute(txn)
        })?;
        StatementResult::try_from(result)
    }

    /// Runs a closure in the session's transaction.
    pub fn with_txn<F, T>(&mut self, read_only: bool, f: F) -> Result<T>
    where
        F: FnOnce(&mut E::Transaction) -> Result<T>,
    {
        if self.txn.is_none() {
            let txn = if read_only {
                self.engine.begin_read_only()?
            } else {
                self.engine.begin()?
            };
            self.txn = Some(txn);
        }

        let txn = self.txn.as_mut().unwrap();
        f(txn)
    }
}

